type Person struct {
	Name string `json:"name"`
	Age  int64  `json:"age"`
}

// Shape is a sealed sum type (revl ADT); isShape() seals it.
type Shape interface{ isShape() }
type ShapeCircle struct{ Value int64 }

func (ShapeCircle) isShape() {}

type ShapeSquare struct{ Value int64 }

func (ShapeSquare) isShape() {}

// service Directory
type Directory interface {
	Make(n string, a int64) Person
	Birthday(p Person) Person
	SecondName(people []Person) string
	Area(s Shape) int64
}

var _keyDir = stc.NewKey[Directory]("dir")

func Registry() stc.Component {
	return stc.Component{
		Name:    "Registry",
		Provide: []stc.Key{_keyDir},
		Apply: func(ctx *stc.Context) (stc.Inverse, error) {
			_implDir := &Registry_dir{ctx: ctx}
			if _, err := ctx.Provide(_keyDir, Directory(_implDir)); err != nil {
				return nil, err
			}
			return nil, nil
		},
	}
}

type Registry_dir struct {
	ctx *stc.Context
}

func (revlSelf *Registry_dir) Make(n string, a int64) Person {
	return Person{Name: n, Age: a}
}

func (revlSelf *Registry_dir) Birthday(p Person) Person {
	return Person{Name: p.Name, Age: (p.Age + 1)}
}

func (revlSelf *Registry_dir) SecondName(people []Person) string {
	return people[1].Name
}

func (revlSelf *Registry_dir) Area(s Shape) int64 {
	return func() int64 {
		switch _m := s.(type) {
		case ShapeCircle:
			r := _m.Value
			_ = r
			return ((r * r) * 3)
		case ShapeSquare:
			w := _m.Value
			_ = w
			return (w * w)
		default:
			_ = _m
			panic("unreachable: non-exhaustive match")
		}
	}()
}

func Front() stc.Component {
	return stc.Component{
		Name:   "Front",
		Inject: []stc.Key{_keyDir},
		Apply: func(ctx *stc.Context) (stc.Inverse, error) {
			dir, err := stc.Service[Directory](ctx, _keyDir)
			if err != nil {
				return nil, err
			}
			_ = dir
			return nil, nil
		},
	}
}

func LoadRegistry(target *stc.Context) *stc.Fiber {
	return target.Load(Registry())
}

func LoadFront(target *stc.Context) *stc.Fiber {
	return target.Load(Front())
}

// ---- lifecycle tests (docs/syntax-2.0.md §7.1) ----------------
// A `lifecycle test` drives the composition on a live stc-go
// context: load components, call through provision keys, unload
// LIFO, and assert no residue (R4 registry + R1 host resources).
type revlOptPair[T any] struct {
	value T
	ok    bool
}

func revlEq(a, b any) bool { return reflect.DeepEqual(a, b) }

func revlListIndexOfEq[T any](xs []T, x T) int64 {
	for i, v := range xs {
		if revlEq(v, x) {
			return int64(i)
		}
	}
	return -1
}

